#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys
import wave
from pathlib import Path

import booster_robotics_sdk_python as br


DEFAULT_VOICE_TYPE = "zh_female_vv_uranus_bigtts"
DEFAULT_PCM_SAMPLE_RATE_HZ = 16000
DEFAULT_PCM_CHANNELS = 1
DEFAULT_PCM_BITS_PER_SAMPLE = 16
WRAPPED_AUDIO_SUFFIXES = {
    ".wav",
    ".mp3",
    ".flac",
    ".ogg",
    ".opus",
    ".m4a",
    ".mp4",
    ".aac",
    ".amr",
    ".webm",
}
FILE_AUDIO_SUFFIXES = {".wav", ".mp3"}


def print_help():
    print(
        """
Available commands (LUI new APIs):
  help
  start_asr
  stop_asr
  start_tts [voice_type]
  stop_tts
  send_tts_text <text>
  synthesize <output_path> <text>
  synthesize_play <output_path> <text>
  recognize_file_once <file_path>
  start_recognizer
  stop_recognizer
  recognize_file_in_session <file_path>
  recognize_pcm_in_session <pcm_file>
  quit / exit

Notes:
  start_asr prints only ASR chunks for the current LuiClient session.
  start_tts must be called before synthesize / synthesize_play.
  recognize_file_once needs no session; it builds a recognizer per request.
  start_recognizer must be called before recognize_file_in_session / recognize_pcm_in_session.
  recognize_pcm_in_session only accepts raw PCM: 16kHz / mono / s16le.
  synthesize writes WAV when output_path ends with .wav, otherwise writes raw PCM bytes.
"""
    )


def on_lui_asr(msg: br.AsrChunk) -> None:
    if msg.is_final and msg.text:
        print(f"\n[ASR] {msg.text}")


def save_audio_response(resp, output_path: str):
    audio_bytes = resp.audio_bytes
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)

    if path.suffix.lower() == ".wav":
        with wave.open(str(path), "wb") as wav_file:
            wav_file.setnchannels(resp.channels)
            wav_file.setsampwidth(max(resp.bits_per_sample // 8, 1))
            wav_file.setframerate(resp.sample_rate_hz)
            wav_file.writeframes(audio_bytes)
    else:
        path.write_bytes(audio_bytes)

    print(
        "[OK] audio saved:",
        f"path={path}",
        f"sample_rate_hz={resp.sample_rate_hz}",
        f"channels={resp.channels}",
        f"bits_per_sample={resp.bits_per_sample}",
        f"format={resp.format}",
        f"audio_bytes={len(audio_bytes)}",
    )


def detect_wrapped_audio_format(audio_bytes: bytes) -> str:
    if len(audio_bytes) >= 12 and audio_bytes[:4] == b"RIFF" and audio_bytes[8:12] == b"WAVE":
        return "wav"
    if len(audio_bytes) >= 3 and audio_bytes[:3] == b"ID3":
        return "mp3"
    if (
        len(audio_bytes) >= 4
        and audio_bytes[0] == 0xFF
        and (audio_bytes[1] & 0xE0) == 0xE0
    ):
        version_bits = (audio_bytes[1] >> 3) & 0x03
        layer_bits = (audio_bytes[1] >> 1) & 0x03
        bitrate_bits = (audio_bytes[2] >> 4) & 0x0F
        sample_rate_bits = (audio_bytes[2] >> 2) & 0x03
        if (
            version_bits != 0x01
            and layer_bits != 0x00
            and bitrate_bits not in (0x00, 0x0F)
            and sample_rate_bits != 0x03
        ):
            return "mp3"
    if len(audio_bytes) >= 4 and audio_bytes[:4] == b"fLaC":
        return "flac"
    if len(audio_bytes) >= 4 and audio_bytes[:4] == b"OggS":
        return "ogg/opus"
    if len(audio_bytes) >= 12 and audio_bytes[4:8] == b"ftyp":
        return "mp4/m4a"
    if len(audio_bytes) >= 2 and audio_bytes[0] == 0xFF and (audio_bytes[1] & 0xF6) == 0xF0:
        return "aac"
    if audio_bytes.startswith(b"#!AMR\n") or audio_bytes.startswith(b"#!AMR-WB\n"):
        return "amr"
    if len(audio_bytes) >= 4 and audio_bytes[:4] == b"\x1A\x45\xDF\xA3":
        return "webm"
    return ""


def build_pcm_request_from_file(pcm_file: str):
    path = Path(pcm_file)
    if path.suffix.lower() in WRAPPED_AUDIO_SUFFIXES:
        raise ValueError(
            "recognize_pcm_in_session only accepts raw PCM files; wrapped audio paths "
            "(.wav/.mp3/.flac/.ogg/.m4a/.aac/...) are not allowed"
        )

    pcm_bytes = path.read_bytes()
    if not pcm_bytes or len(pcm_bytes) % 2 != 0:
        raise ValueError("recognize_pcm_in_session expects 16-bit little-endian raw PCM bytes")

    wrapped_audio_format = detect_wrapped_audio_format(pcm_bytes)
    if wrapped_audio_format:
        if wrapped_audio_format in ("wav", "mp3"):
            raise ValueError(
                f"recognize_pcm_in_session detected {wrapped_audio_format} content; "
                "use recognize_file_in_session instead"
            )
        raise ValueError(
            f"recognize_pcm_in_session detected wrapped audio ({wrapped_audio_format}); "
            "convert it to 16kHz mono 16-bit little-endian raw PCM first"
        )

    return br.LuiRecognizeAudioRequest.FromPcmBytes(
        pcm_bytes=pcm_bytes,
        sample_rate_hz=DEFAULT_PCM_SAMPLE_RATE_HZ,
        channels=DEFAULT_PCM_CHANNELS,
        bits_per_sample=DEFAULT_PCM_BITS_PER_SAMPLE,
        format="pcm_s16le",
    )


def build_file_request(file_path: str):
    path = Path(file_path)
    if path.suffix.lower() not in FILE_AUDIO_SUFFIXES:
        raise ValueError(
            "recognize_file_in_session only accepts .wav or .mp3 paths; "
            "use recognize_pcm_in_session for raw PCM"
        )
    return br.LuiRecognizeAudioRequest.FromFile(file_path)


def parse_command(line: str):
    parts = line.strip().split(maxsplit=2)
    cmd = parts[0]
    arg1 = parts[1] if len(parts) > 1 else ""
    arg2 = parts[2] if len(parts) > 2 else ""
    return cmd, arg1, arg2


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} networkInterface [robotName]")
        sys.exit(-1)

    net_if = sys.argv[1]
    robot_name = sys.argv[2] if len(sys.argv) > 2 else None

    br.ChannelFactory.Instance().Init(0, net_if)

    lui = br.LuiClient()
    if robot_name:
        lui.InitWithName(robot_name)
    else:
        lui.Init()

    asr_sub = None

    print("LUI new API CLI started.")
    print_help()

    while True:
        try:
            line = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nExit.")
            break

        if not line:
            continue

        cmd, arg1, arg2 = parse_command(line)

        try:
            if cmd in ("help", "?"):
                print_help()

            elif cmd == "start_asr":
                if asr_sub is not None:
                    asr_sub.CloseChannel()
                lui.StartAsr()
                asr_sub = br.LuiAsrChunkSubscriber(on_lui_asr)
                if robot_name:
                    asr_sub.InitChannelForClientWithName(lui, robot_name)
                else:
                    asr_sub.InitChannelForClient(lui)
                print("[OK] StartAsr sent. Speak to receive ASR chunks.")

            elif cmd == "stop_asr":
                lui.StopAsr()
                if asr_sub is not None:
                    asr_sub.CloseChannel()
                    asr_sub = None
                print("[OK] StopAsr sent.")

            elif cmd == "start_tts":
                voice_type = arg1 if arg1 else DEFAULT_VOICE_TYPE
                lui.StartTts(br.LuiTtsConfig(voice_type))
                print(f"[OK] StartTts sent, voice_type={voice_type}")

            elif cmd == "stop_tts":
                lui.StopTts()
                print("[OK] StopTts sent.")

            elif cmd == "send_tts_text":
                text = line[len("send_tts_text") :].strip()
                if not text:
                    print("Usage: send_tts_text <text>")
                    continue
                lui.SendTtsText(br.LuiTtsParameter(text))
                print(f"[OK] SendTtsText sent: {text}")

            elif cmd in ("synthesize", "synthesize_play"):
                if not arg1 or not arg2:
                    print(f"Usage: {cmd} <output_path> <text>")
                    continue
                req = br.LuiSynthesizeSpeechRequest(
                    text=arg2,
                    voice_type=DEFAULT_VOICE_TYPE,
                    speed=1.0,
                    playback=(cmd == "synthesize_play"),
                )
                resp = lui.SynthesizeSpeech(req)
                save_audio_response(resp, arg1)

            elif cmd == "recognize_file_once":
                if not arg1:
                    print("Usage: recognize_file_once <file_path>")
                    continue
                req = build_file_request(arg1)
                resp = lui.RecognizeAudioOnce(req)
                print(f"[OK] one-shot recognize success: {resp.text}")

            elif cmd == "start_recognizer":
                lui.StartAudioRecognizer()
                print("[OK] StartAudioRecognizer sent.")

            elif cmd == "stop_recognizer":
                lui.StopAudioRecognizer()
                print("[OK] StopAudioRecognizer sent.")

            elif cmd == "recognize_file_in_session":
                if not arg1:
                    print("Usage: recognize_file_in_session <file_path>")
                    continue
                req = build_file_request(arg1)
                resp = lui.RecognizeAudioInSession(req)
                print(f"[OK] in-session recognize success: {resp.text}")

            elif cmd == "recognize_pcm_in_session":
                if not arg1:
                    print("Usage: recognize_pcm_in_session <pcm_file>")
                    continue
                req = build_pcm_request_from_file(arg1)
                resp = lui.RecognizeAudioInSession(req)
                print(f"[OK] in-session recognize success: {resp.text}")

            elif cmd in ("quit", "exit"):
                print("Bye.")
                break

            else:
                print(f"Unknown command: {cmd}")
                print("Type 'help' to show available commands.")

        except Exception as e:
            print(f"[ERROR] Request failed: {e}")


if __name__ == "__main__":
    main()
